                  </div>
                </li>
              </ul>
            </div>
          </div>
        </li>
        </template>

        <template v-if="groupVisible('lm')">
        <li id="research-models" class="timeline-group-section" :class="{ collapsed: !isGroupExpanded('lm') }">
          <button class="timeline-group" type="button" :aria-expanded="isGroupExpanded('lm') ? 'true' : 'false'" @click="toggleGroup('lm')">
            <span class="tl-label">Language models, behavior, and interpretability</span>
            <span class="tl-count">{{ groupCount('lm') }}</span>
            <span class="tl-caret" aria-hidden="true"></span>
          </button>
          <p class="timeline-note">What language models represent, compute, and control internally.</p>
          <div class="tl-group-body">
            <div class="tl-group-inner">
              <ul class="timeline-group-items">
                <li v-for="pub in groupItems('lm')" :key="pub.id" :id="pub.anchor || pub.id" class="timeline-event">
                  <div class="timeline-event-copy">
                    <p class="timeline-event-thumbnail">{{ pub.period }}</p>
                    <h3 v-html="hlText(pub.title)"></h3>
                    <h4 v-if="pub.lab">Associated with <a :href="pub.lab.url" target="_blank" rel="noopener"><b>{{ pub.lab.name }}</b></a></h4>
                    <img v-if="pub.lab && pub.lab.logo" :src="pub.lab.logo" class="slr-lab-logo" :style="{ height: pub.lab.logoHeight || '11vh' }" :alt="pub.lab.name">
                    <p v-html="hlHtml(pubDesc[pub.id])"></p>
                    <div v-if="pub.images.length" class="scroll-container project">
                      <img v-for="(image, index) in pub.images" :key="image" :src="imageThumb(image)" :data-full-src="imageFull(image)" :alt="`${pub.title}, figure ${index + 1}`" loading="lazy" decoding="async">
