        </template>

      </ul>
      <p v-if="searchActive && !hasSearchMatches" class="timeline-empty">No matching research entries.</p>
    </article>
  </div>
</template>

<script>
import scrollRevealMixin from '../mixins/scrollRevealMixin';
import { publicationDescriptions } from '../data/publications';
import { researchPublications } from '../data/researchPublications';
import { highlightText, highlightHtml } from '../utils/highlight';
import ChapterRail from './ChapterRail.vue';
import PublicationMeta from './PublicationMeta.vue';

export default {
  name: 'ResearchTab',
  components: { ChapterRail, PublicationMeta },
  mixins: [scrollRevealMixin],
  data() {
    return {
      introExpanded: false,
      expanded: { human: true, lm: true, humanAi: true },
      searchQuery: '',
      pubDesc: publicationDescriptions
    };
  },
  computed: {
    searchTerms() {
      return this.searchQuery
        .toLowerCase()
        .split(/[\s,.;:!?()[\]{}"']+/)
        .map((term) => term.trim())
        .filter((term) => term.length >= 2);
    },
    searchActive() {
      return this.searchTerms.length > 0;
    },
    hasSearchMatches() {
      return researchPublications.some((entry) => this.entryMatches(entry.id));
    },
    chapterItems() {
      return [
        { key: 'humanAi', id: 'research-human-ai', label: 'Human × AI', title: 'Human-AI interaction and collaboration' },
        { key: 'human', id: 'research-human', label: 'Human learning', title: 'Human learning and computational cognition' },
        { key: 'lm', id: 'research-models', label: 'Model interpretability', title: 'Language models, behavior, and interpretability' }
      ].filter((item) => this.groupVisible(item.key));
    }
  },
  watch: {
    '$route.hash'() {
      this.scrollToRouteHash();
    },
    searchQuery() {
      this.refreshScrollReveal();
    }
  },
  methods: {
    scrollToRouteHash(attempt = 0) {
      const hash = this.$route && this.$route.hash ? this.$route.hash : '';
      if (!hash) return;

      let id = hash.replace(/^#/, '');
      try {
        id = decodeURIComponent(id);
      } catch (error) {
        // Keep the original hash text when it is already plain text.
      }

      this.$nextTick(() => {
        const target = document.getElementById(id);
        if (target) {
          target.scrollIntoView({ block: 'start', behavior: 'auto' });
          this.refreshScrollReveal();
          window.dispatchEvent(new Event('scroll'));
          return;
        }

        if (attempt < 20) {
          window.setTimeout(() => this.scrollToRouteHash(attempt + 1), 80);
        }
      });
    },
    stripHtml(text) {
      return String(text || '').replace(/<[^>]+>/g, ' ');
    },
    hlText(text) {
      return highlightText(text, this.searchTerms);
    },
    hlHtml(html) {
      return highlightHtml(html, this.searchTerms);
    },
    imageThumb(name) {
      return `/assets/img/gallery-thumbs/${name}.png.webp`;
    },
    imageFull(name) {
      return `/assets/img/${name}.png`;
    },
    entryById(id) {
      return researchPublications.find((entry) => entry.id === id);
    },
    entrySearchText(entry) {
      return [
        entry.title,
        entry.text,
        this.stripHtml(this.pubDesc[entry.id])
      ].join(' ').toLowerCase();
    },
    entryMatches(id) {
      const entry = this.entryById(id);
      if (!entry) return false;
      const text = this.entrySearchText(entry);
      return this.searchTerms.every((term) => text.includes(term));
    },
    groupMatches(groupKey) {
      return researchPublications
        .filter((entry) => entry.group === groupKey)
        .some((entry) => this.entryMatches(entry.id));
    },
    groupCount(groupKey) {
      return researchPublications
        .filter((entry) => entry.group === groupKey && this.entryMatches(entry.id))
        .length;
    },
    groupItems(groupKey) {
      return researchPublications.filter((entry) => (
        entry.group === groupKey && this.entryMatches(entry.id)
      ));
    },
    groupVisible(groupKey) {
      if (!this.searchActive) return true;
      return this.groupMatches(groupKey);
    },
    isGroupExpanded(groupKey) {
      if (this.searchActive) return this.groupMatches(groupKey);
      return this.expanded[groupKey];
    },
    entryVisible(id) {
      if (!this.searchActive) return true;
      return this.entryMatches(id);
    },
    toggleIntro() {
      const wasExpanded = this.introExpanded;
      this.introExpanded = !this.introExpanded;
      this.$nextTick(() => {
        this.refreshScrollReveal();
        if (wasExpanded && this.$refs.researchTop) {
          this.$refs.researchTop.scrollIntoView({
            behavior: 'smooth',
            block: 'start'
          });
        }
      });
    },
    toggleGroup(groupKey) {
      if (this.searchActive) return;
      this.expanded = {
        ...this.expanded,
        [groupKey]: !this.expanded[groupKey]
      };
      this.refreshScrollReveal();
    },
    clearSearch() {
      this.searchQuery = '';
    }
  }
}
</script>

