<script>
import scrollRevealMixin from '../mixins/scrollRevealMixin';
import ChapterRail from './ChapterRail.vue';

export default {
  name: 'ExperienceTab',
  components: { ChapterRail },
  mixins: [scrollRevealMixin],
  data() {
    return {
      chapterItems: [
        { id: 'work-pwc', label: 'PwC' },
        { id: 'work-slr', label: 'SLR' },
        { id: 'work-hsbc', label: 'HSBC' },
        { id: 'work-pds', label: 'PDS' },
        { id: 'work-kiwiview', label: 'Kiwiview' }
      ]
    };
  },
  watch: {
    '$route.hash'() {
      this.scrollToRouteHash();
    }
  },
  methods: {
    scrollToRouteHash(attempt = 0) {
      const hash = this.$route && this.$route.hash ? this.$route.hash : '';
      if (!hash) return;

      let id = hash.replace(/^#/, '');
      try {
        id = decodeURIComponent(id);
      } catch (error) {
        // Keep the original hash text when it is already plain text.
      }

      this.$nextTick(() => {
        const target = document.getElementById(id);
        if (target) {
          target.scrollIntoView({ block: 'start', behavior: 'auto' });
          this.refreshScrollReveal();
          window.dispatchEvent(new Event('scroll'));
          return;
        }

        if (attempt < 20) {
          window.setTimeout(() => this.scrollToRouteHash(attempt + 1), 80);
        }
      });
    }
  }
}
</script>

