<template>
  <div class="container" :class="{ 'margin-dock-active': marginDockActive }">
    <div class="scroll-progress" v-show="showScrollProgress && !previewMode" :style="{ transform: 'scaleX(' + scrollPct + ')' }"></div>
    <header class="header" :class="{ 'home-direct-nav': directHomeNavHidden, 'intro-root': isIntroRoot }" v-show="!cvChromeHidden && !previewMode">
      <h3 class="header-title">
        <router-link to="/home">H.W.</router-link>
        <small class="header-subtitle">An enthusiastic explorer</small>
        <div class="menu">
          <nav class="menu-content" :class="'nav-tabs-' + navTabsLayout">
            <router-link to="/about" class="menu-item about">About</router-link>
            <router-link to="/education" class="menu-item education">Study</router-link>
            <router-link to="/experience" class="menu-item experience">Work</router-link>
            <router-link to="/research" class="menu-item research">Research</router-link>
            <router-link to="/projects" class="menu-item projects">Builds</router-link>
            <router-link to="/fragments" class="menu-item fragments">Fragments</router-link>
          </nav>
          <nav class="social-icons" aria-label="Site controls">
            <button class="site-control search-trigger" type="button" title="Ask or search (⌘K)" aria-label="Ask or search" @click="openSearch"><i class="fa fa-search" aria-hidden="true"></i></button>
            <button id="toggle-theme" class="site-control" type="button" title="Toggle Theme" aria-label="Toggle theme"><i class="fa fa-moon" aria-hidden="true"></i></button>
            <button id="music-icon" class="site-control" type="button" title="Play Music" aria-label="Play music"><i class="fa fa-compact-disc" aria-hidden="true"></i></button>
          </nav>
        </div>
        <audio id="background-music"></audio>
      </h3>
    </header>
    <aside
      class="margin-dock-left"
      v-show="marginDockActive && !previewMode"
      aria-label="Site identity and navigation"
      @mouseenter="holdDockPin"
      @mouseleave="releaseDockPin"
    >
      <router-link to="/home" class="margin-dock-identity">H.W.</router-link>
      <small class="margin-dock-subtitle">An enthusiastic explorer</small>
      <nav class="margin-dock-nav" aria-label="Site navigation" @click="pinDock">
        <router-link to="/about" class="margin-dock-item">About</router-link>
        <router-link to="/education" class="margin-dock-item">Study</router-link>
        <router-link to="/experience" class="margin-dock-item">Work</router-link>
        <router-link to="/research" class="margin-dock-item">Research</router-link>
        <router-link to="/projects" class="margin-dock-item">Builds</router-link>
        <router-link to="/fragments" class="margin-dock-item">Fragments</router-link>
      </nav>
    </aside>
    <nav
      class="margin-dock-controls"
      v-show="marginDockActive && !previewMode"
      aria-label="Persistent site controls"
      @mouseenter="holdDockPin"
      @mouseleave="releaseDockPin"
    >
      <div class="margin-dock-control-zone margin-dock-theme-zone">
        <button class="site-control margin-dock-control margin-dock-theme" type="button" :aria-label="dockThemeLabel" @pointerup="releaseDockPointerFocus" @click="toggleThemeFromDock">
          <i :class="dockThemeIconClass" aria-hidden="true"></i>
        </button>
      </div>
      <div class="margin-dock-control-zone margin-dock-search-zone">
        <button class="site-control margin-dock-control margin-dock-search" type="button" aria-label="Ask or search" @pointerup="releaseDockPointerFocus" @click="openSearch">
          <i class="fa fa-search" aria-hidden="true"></i>
        </button>
      </div>
      <div class="margin-dock-control-zone margin-dock-music-zone">
        <button class="site-control margin-dock-control margin-dock-music" type="button" :aria-label="dockMusicLabel" @pointerup="releaseDockPointerFocus" @click="toggleMusicFromDock">
          <i :class="dockMusicIconClass" aria-hidden="true"></i>
        </button>
      </div>
    </nav>
    <div class="content-container" :class="{ 'cv-route': isCv }">
      <router-view v-slot="{ Component }">
        <transition :name="routeTransitionName" mode="out-in" @before-enter="beforeRouteEnter">
          <component :is="Component" />
        </transition>
      </router-view>
    </div>
    <footer class="footer" :class="{ 'home-direct-nav': directHomeNavHidden }" v-show="!cvChromeHidden && !previewMode">
      <a href="https://www.instagram.com/henry_w_hy/" target="_blank">
        <i class="fab fa-instagram" aria-hidden="true"></i>
      </a>
      <a href="https://www.linkedin.com/in/henrywhy/" target="_blank">
        <i class="fab fa-linkedin" aria-hidden="true"></i>
      </a>
      <a href="https://github.com/henryhyw/" target="_blank">
        <i class="fab fa-github" aria-hidden="true"></i>
      </a>
      <router-link to="/cv" title="CV" aria-label="CV">
        <i class="far fa-file-alt" aria-hidden="true"></i>
      </router-link>
      <router-link
        to="/travels"
        class="footer-compass"
        :class="footerCompassSpin"
        title="Travels"
        aria-label="Travels"
        @mouseenter="spinFooterCompass('in')"
        @mouseleave="spinFooterCompass('out')"
      >
        <i class="far fa-compass" aria-hidden="true"></i>
      </router-link>
      <div class="footer-description">
        <a><router-link to="/home">H.W. | An enthusiastic explorer</router-link></a>
      </div>
    </footer>
    <SearchPalette ref="search" />
  </div>
</template>

<script>
import SearchPalette from './components/SearchPalette.vue';
import { initCircularMediaRails } from './utils/mediaRails';
import { animate } from 'motion';

// The dock elements only ever translate (resting transforms are pure
// translateY), so the live on-screen offset is just the matrix translation.
function currentTranslation(element) {
  try {
    const m = new DOMMatrix(getComputedStyle(element).transform);
    return { x: m.m41, y: m.m42 };
  } catch (e) {
    return { x: 0, y: 0 };
  }
}

export default {
  name: 'App',
  components: { SearchPalette },
  data() {
    return {
      scrollPct: 0,
      navTabsLayout: 'one',
      cvChromeHidden: false,
      footerCompassSpin: '',
      marginDockActive: false,
      marginDockPinned: false,
      dockHoverCount: 0,
      dockThemeIconClass: 'fa fa-moon',
      dockThemeLabel: 'Toggle theme',
      dockMusicIconClass: 'fa fa-compact-disc',
      dockMusicLabel: 'Play music',
      directHomeNavHidden:
        typeof window !== 'undefined'
        && /^#\/(?:$|[?#])/.test(window.location.hash || ''),
    };
  },
  computed: {
    previewMode() {
      return this.$route.query.preview === '1';
    },
    isIntroRoot() {
      return this.$route.path === '/';
    },
    isCv() {
      return this.$route.path === '/cv';
    },
    showScrollProgress() {
      return !this.isCv && this.$route.path !== '/home' && this.$route.path !== '/';
    },
    routeTransitionName() {
      return ['/research', '/projects', '/fragments'].includes(this.$route.path)
        ? 'fade-slide'
        : 'route-fade';
    }
  },
  watch: {
    '$route.path'(path, previousPath) {
      if (previousPath === '/' && path !== '/') {
        this.$nextTick(this.resetIntroChromeStyles);
      }
    },
    isCv(onCv, wasCv) {
      if (this._cvChromeRevealTimer) {
        clearTimeout(this._cvChromeRevealTimer);
        this._cvChromeRevealTimer = null;
      }
      if (onCv) {
        // Hide the chrome the moment the route changes, before the page
        // transition runs, so the header never flashes on the way in.
        this.cvChromeHidden = true;
        this.pauseMusicForCv();
      } else if (wasCv || this.cvChromeHidden) {
        this._cvChromeRevealTimer = setTimeout(() => {
          this._cvChromeRevealTimer = null;
          if (!this.isCv) {
            this.cvChromeHidden = false;
            this.$nextTick(() => this.scheduleNavTabsLayout({ retries: 4 }));
          }
        }, 280);
      }
    }
  },
  mounted() {
    this._cleanupMediaRails = initCircularMediaRails();
    this.script1 = document.createElement('script');
    this.script1.src = '/assets/js/default.js';
    this.script1.async = true;
    document.body.appendChild(this.script1);
    this.script2 = document.createElement('script');
    this.script2.src = '/assets/js/theme-toggle.js';
    this.script2.async = true;
    document.body.appendChild(this.script2);
    this.$nextTick(this.setupDockControlSync);
    if (this.isCv) {
      this.cvChromeHidden = true;
      this.$nextTick(this.pauseMusicForCv);
    }
    this._onScroll = this.handleScroll;
    window.addEventListener('scroll', this._onScroll, { passive: true });
    this.handleScroll();

    this._onDirectHomeNavRevealed = () => {
      this.directHomeNavHidden = false;
      this.$nextTick(() => {
        this.refreshMarginDockThreshold();
        this.updateMarginDock();
      });
    };
    window.addEventListener('home-direct-nav-revealed', this._onDirectHomeNavRevealed);
    this._onResize = () => {
      this.scheduleNavTabsLayout();
      this.updateMarginDock({ instant: true, refreshThreshold: true });
    };
    window.addEventListener('resize', this._onResize, { passive: true });
    this.$nextTick(() => {
      this.scheduleNavTabsLayout();
      this.refreshMarginDockThreshold();
      this.updateMarginDock({ instant: true });
    });
    if (document.fonts && document.fonts.ready) {
      document.fonts.ready.then(this.scheduleNavTabsLayout).catch(() => {});
    }
  },
  unmounted() {
    if (this._cleanupMediaRails) {
      this._cleanupMediaRails();
      this._cleanupMediaRails = null;
    }
    window.removeEventListener('scroll', this._onScroll);
    window.removeEventListener('home-direct-nav-revealed', this._onDirectHomeNavRevealed);
    window.removeEventListener('resize', this._onResize);
    if (this._navLayoutRaf) {
      cancelAnimationFrame(this._navLayoutRaf);
      this._navLayoutRaf = null;
    }
    if (this._cvChromeRevealTimer) {
      clearTimeout(this._cvChromeRevealTimer);
      this._cvChromeRevealTimer = null;
    }
    if (this._footerCompassSpinRaf) {
      cancelAnimationFrame(this._footerCompassSpinRaf);
      this._footerCompassSpinRaf = null;
    }
    this.cancelMarginDockAnimations();
    if (this._dockControlObserver) {
      this._dockControlObserver.disconnect();
      this._dockControlObserver = null;
    }
    // Clean up the scripts when the component is destroyed
    if (this.script1 && this.script1.parentNode) {
      this.script1.parentNode.removeChild(this.script1);
    }
    if (this.script2 && this.script2.parentNode) {
      this.script2.parentNode.removeChild(this.script2);
    }
  },
  methods: {
    resetIntroChromeStyles() {
      if (!this.$el) return;
      const selectors = [
        '.header-title > a',
        '.header-subtitle',
        '.menu-content a',
        '.social-icons button',
        '.footer a',
        '.footer-description',
      ];
      this.$el.querySelectorAll(selectors.join(',')).forEach((element) => {
        ['color', 'opacity', 'transform', 'transition'].forEach((property) => {
          element.style.removeProperty(property);
        });
        const glyph = element.querySelector('i');
        if (glyph) glyph.style.removeProperty('color');
      });
    },
    beforeRouteEnter(el) {
      const enteringCv = el && el.classList && el.classList.contains('cv-root');
      this.cvChromeHidden = enteringCv;
      if (!enteringCv) {
        this.$nextTick(() => this.scheduleNavTabsLayout({ retries: 4 }));
      }
    },
    openSearch() {
      this.$refs.search.openPalette('pointer');
    },
    setupDockControlSync() {
      const theme = document.getElementById('toggle-theme');
      const music = document.getElementById('music-icon');
      if (!theme || !music) return;
      this.syncDockControlState();
      this._dockControlObserver = new MutationObserver(this.syncDockControlState);
      [theme, music].forEach((button) => {
        this._dockControlObserver.observe(button, {
          attributes: true,
          subtree: true,
          attributeFilter: ['aria-label', 'class', 'title'],
        });
      });
    },
    syncDockControlState() {
      const theme = document.getElementById('toggle-theme');
      const music = document.getElementById('music-icon');
      const themeIcon = theme && theme.querySelector('i');
      const musicIcon = music && music.querySelector('i');
      if (themeIcon) this.dockThemeIconClass = themeIcon.className;
      if (musicIcon) this.dockMusicIconClass = musicIcon.className;
      if (theme) this.dockThemeLabel = theme.getAttribute('aria-label') || 'Toggle theme';
      if (music) this.dockMusicLabel = music.getAttribute('aria-label') || 'Play music';
    },
    toggleThemeFromDock() {
      const theme = document.getElementById('toggle-theme');
      if (theme) theme.click();
    },
    toggleMusicFromDock() {
      const music = document.getElementById('music-icon');
      if (music) music.click();
    },
    releaseDockPointerFocus(event) {
      if (event.currentTarget) event.currentTarget.blur();
    },
    spinFooterCompass(direction) {
      if (this._footerCompassSpinRaf) {
        cancelAnimationFrame(this._footerCompassSpinRaf);
      }
      this.footerCompassSpin = '';
      this._footerCompassSpinRaf = requestAnimationFrame(() => {
        this._footerCompassSpinRaf = null;
        this.footerCompassSpin = direction === 'out'
          ? 'footer-compass-spin-out'
          : 'footer-compass-spin-in';
      });
    },
    handleScroll() {
      const el = document.documentElement;
      const max = el.scrollHeight - el.clientHeight;
      this.scrollPct = max > 0 ? Math.min(Math.max(el.scrollTop / max, 0), 1) : 0;
      this.updateMarginDock();
    },
    canUseMarginDock() {
      return !this.cvChromeHidden
        && !this.directHomeNavHidden
        && window.matchMedia('(min-width: 840px) and (min-height: 620px) and (hover: hover) and (pointer: fine)').matches;
    },
    marginDockElements() {
      if (!this.$el) return [];
      const identity = this.$el.querySelector('.margin-dock-identity');
      const subtitle = this.$el.querySelector('.margin-dock-subtitle');
      const menuItems = Array.from(this.$el.querySelectorAll('.margin-dock-nav .margin-dock-item'));
      const controls = Array.from(this.$el.querySelectorAll('.margin-dock-controls .margin-dock-control'));
      return [
        identity && { element: identity, kind: 'identity', order: 0 },
        subtitle && { element: subtitle, kind: 'subtitle', order: 0 },
        ...menuItems.map((element, order) => ({ element, kind: 'menu', order })),
        ...controls.map((element, order) => ({ element, kind: 'control', order })),
      ].filter(Boolean);
    },
    refreshMarginDockThreshold() {
      if (this.marginDockActive || !this.$el) return;
      const header = this.$el.querySelector('.header');
      if (!header) return;
      this._marginDockThreshold = header.offsetTop + header.offsetHeight + 12;
    },
    updateMarginDock(options = {}) {
      const { instant = false, refreshThreshold = false } = options;
      if (refreshThreshold) this.refreshMarginDockThreshold();
      if (!this.canUseMarginDock()) {
        this.setMarginDock(false, { instant: true });
        return;
      }
      if (!Number.isFinite(this._marginDockThreshold)) {
        this.refreshMarginDockThreshold();
      }
      if (!Number.isFinite(this._marginDockThreshold)) return;

      const exitThreshold = Math.max(0, this._marginDockThreshold - 42);
      const shouldDock = this.marginDockActive
        ? (window.scrollY > exitThreshold || this.marginDockPinned)
        : window.scrollY > this._marginDockThreshold;
      this.setMarginDock(shouldDock, { instant });
    },
    cancelMarginDockAnimations() {
      if (!this._marginDockAnimations) return;
      this._marginDockAnimations.forEach((animation) => animation.stop());
      this._marginDockAnimations = [];
    },
    // A dock nav click keeps the dock visible after the route lands at the top
    // of the new page, so the jump does not feel like the chrome vanishes.
    // The dock then stays until the pointer leaves both side rails.
    pinDock(event) {
      if (!this.canUseMarginDock()) return;
      if (event && event.target && !event.target.closest('.margin-dock-item')) return;
      this.marginDockPinned = true;
      this.updateMarginDock();
    },
    holdDockPin() {
      if (!this.canUseMarginDock()) return;
      this.dockHoverCount += 1;
    },
    releaseDockPin() {
      if (!this.canUseMarginDock()) return;
      this.dockHoverCount = Math.max(0, this.dockHoverCount - 1);
      if (this.dockHoverCount > 0) return;
      this.marginDockPinned = false;
      this.updateMarginDock();
    },
    setMarginDock(active, options = {}) {
      const currentTarget = this._marginDockTarget ?? this.marginDockActive;
      if (currentTarget === active) return;
      this._dockSettleToken = (this._dockSettleToken || 0) + 1;
      const { instant = false } = options;
      const reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      const elements = this.marginDockElements();
      this._marginDockTarget = active;
      this.cancelMarginDockAnimations();

      if (instant || reduceMotion) {
        this.marginDockActive = active;
        return;
      }

      if (active) this.marginDockActive = true;

      if (!this._dockResting) this._dockResting = new WeakMap();
      if (!this._dockWasAnimated) this._dockWasAnimated = new WeakSet();

      this.$nextTick(() => {
        requestAnimationFrame(() => {
          const animations = [];
          elements.forEach(({ element, kind, order }) => {
            if (!element.isConnected) return;
            const rect = element.getBoundingClientRect();
            if (!rect.width || !rect.height) return;

            // Capture the CSS resting transform once, before any spring leaves
            // an inline style behind. Stopping a Motion animation keeps the
            // element where it was, so later reads give the live on-screen
            // value and a scroll reversal starts from there, never from a
            // logical target.
            let rest = this._dockResting.get(element);
            if (!rest) {
              const atRest = currentTranslation(element);
              rest = { ...atRest, opacity: getComputedStyle(element).opacity };
              this._dockResting.set(element, rest);
            }
            const current = currentTranslation(element);
            const edgeOffset = kind === 'control'
              ? window.innerWidth - rect.left + 16
              : -(rect.right + 16);

            // Enter flies in from the margin edge on first activation; after
            // that, both directions start from wherever the dock currently is.
            const firstTime = !this._dockWasAnimated.has(element);
            const fromX = active
              ? (firstTime ? rest.x + edgeOffset : current.x)
              : current.x;
            const fromY = active
              ? (firstTime ? rest.y : current.y)
              : current.y;
            const toX = active ? rest.x : rest.x + edgeOffset;
            const toY = rest.y;
            const fromOpacity = active
              ? (firstTime ? 0 : Number(getComputedStyle(element).opacity))
              : Number(getComputedStyle(element).opacity);
            const toOpacity = active ? Number(rest.opacity) : 0;

            // Spring response, not duration: critically damped (no overshoot),
            // snappier for the smaller pieces and for the exit.
            const response = active
              ? ({ identity: 0.4, subtitle: 0.36, menu: 0.32, control: 0.3 }[kind] || 0.34)
              : 0.24;
            const delay = active
              ? (kind === 'identity'
                ? 0
                : kind === 'subtitle'
                  ? 0.05
                  : kind === 'menu'
                    ? 0.06 + order * 0.016
                    : order * 0.02)
              : (kind === 'menu' ? Math.max(0, 5 - order) * 0.012 : 0);

            const animation = animate(element, {
              transform: [
                `translate3d(${fromX}px, ${fromY}px, 0)`,
                `translate3d(${toX}px, ${toY}px, 0)`,
              ],
              opacity: [fromOpacity, toOpacity],
            }, {
              type: 'spring',
              bounce: 0,
              duration: response,
              delay,
            });
            this._dockWasAnimated.add(element);
            animations.push(animation);
          });
          this._marginDockAnimations = animations;

          Promise.all(animations.map((animation) => animation.finished.catch(() => {})))
            .then(() => {
              if (this._marginDockAnimations !== animations) return;
              if (!active && this._marginDockTarget === false) {
                this.marginDockActive = false;
              }
              animations.forEach((animation) => animation.stop());
              this._marginDockAnimations = [];
              if (active) {
                // The springs leave inline transform/opacity pinned on the
                // elements, which blocks the stylesheet hover and active
                // feedback. Once the dock has settled, clear them so CSS
                // drives the resting state. A delayed spring can commit its
                // final keyframe after the completion fires, so re-clear on a
                // short guarded timer until every element has settled.
                const settleToken = this._dockSettleToken;
                const clearInline = () => {
                  if (this._dockSettleToken !== settleToken) return;
                  if (this._marginDockAnimations && this._marginDockAnimations.length) return;
                  elements.forEach(({ element }) => {
                    if (!element.isConnected) return;
                    element.style.transform = '';
                    element.style.opacity = '';
                  });
                };
                clearInline();
                [160, 480].forEach((ms) => setTimeout(clearInline, ms));
              }
              if (!active) this.$nextTick(this.refreshMarginDockThreshold);
            });
        });
      });
    },
    scheduleNavTabsLayout(options = {}) {
      const retries = options.retries || 0;
      if (this._navLayoutRaf) cancelAnimationFrame(this._navLayoutRaf);
      this._navLayoutRaf = requestAnimationFrame(() => {
        this._navLayoutRaf = null;
        const updated = this.updateNavTabsLayout();
        if (!updated && retries > 0) {
          this.scheduleNavTabsLayout({ retries: retries - 1 });
        }
      });
    },
    updateNavTabsLayout() {
      if (this.cvChromeHidden) return false;

      const header = this.$el && this.$el.querySelector('.header');
      const menu = this.$el && this.$el.querySelector('.menu');
      const tabs = this.$el && this.$el.querySelector('.menu-content');
      const icons = this.$el && this.$el.querySelector('.social-icons');
      if (!header || !menu || !tabs || !icons) return false;
      if (getComputedStyle(header).display === 'none') return false;

      const items = Array.from(tabs.querySelectorAll('.menu-item'));
      if (items.length !== 6) return false;

      const menuWidth = menu.getBoundingClientRect().width;
      const widths = items.map((item) => item.getBoundingClientRect().width);
      const iconsWidth = icons.getBoundingClientRect().width;
      if (menuWidth <= 0 || iconsWidth <= 0 || widths.some((width) => width <= 0)) {
        return false;
      }

      const gap = parseFloat(getComputedStyle(tabs).columnGap) || 0;
      const availableWidth = Math.max(0, menuWidth - iconsWidth);
      const layoutWidth = (cols) => {
        const colWidths = Array.from({ length: cols }, (_, col) => {
          let max = 0;
          for (let i = col; i < widths.length; i += cols) {
            max = Math.max(max, widths[i]);
          }
          return max;
        });
        return colWidths.reduce((sum, width) => sum + width, 0) + gap * (cols - 1);
      };

      if (layoutWidth(6) <= availableWidth) {
        this.navTabsLayout = 'one';
      } else if (layoutWidth(3) <= availableWidth) {
        this.navTabsLayout = 'two';
      } else {
        this.navTabsLayout = 'three';
      }
      return true;
    },
    pauseMusicForCv() {
      const music = document.getElementById('background-music');
      const musicIcon = document.getElementById('music-icon');
      if (!music) {
        return;
      }

      music.pause();
      localStorage.setItem('musicPlaying', 'false');
      if (music.currentTime) {
        localStorage.setItem('musicTime', music.currentTime);
      }

      const icon = musicIcon && musicIcon.querySelector('i');
      if (icon) {
        icon.classList.remove('fa-spin');
      }
      if (musicIcon) {
        musicIcon.title = 'Play Music';
        musicIcon.setAttribute('aria-label', 'Play music');
      }
    }
  }
}
</script>

<style>
    @import url('./assets/css/main.css');
    @import url('./assets/css/syntax.css');
