<template>
  <div class="pub-cite">
    <p v-if="pub.status" class="pub-cite-venue">{{ pub.status }}</p>
    <h4 class="pub-cite-title">
      <a
        v-if="paperUrl"
        :href="paperUrl"
        target="_blank"
        rel="noopener"
        v-html="hlText(pub.title)"
      ></a>
      <span v-else v-html="hlText(pub.title)"></span>
    </h4>
    <p v-if="pub.authors" class="pub-cite-authors" v-html="hlHtml(authorsHtml)"></p>
    <p v-if="extraLinks.length" class="pub-cite-links">
      <a
        v-for="link in extraLinks"
        :key="link.label"
        class="pub-cite-link"
        :href="link.url"
        target="_blank"
        rel="noopener"
      >
        {{ link.label }}
        <span class="pub-cite-arrow" aria-hidden="true">&rarr;</span>
      </a>
    </p>
  </div>
</template>

<script>
import {
  highlightText,
  highlightHtml,
  escapeHtml,
  escapeRegExp
} from '../utils/highlight';

export default {
  name: 'PublicationMeta',
  props: {
    pub: {
      type: Object,
      required: true
    },
    searchTerms: {
      type: Array,
      default: () => []
    }
  },
  computed: {
    paperUrl() {
      const paper = (this.pub.links || []).find((link) => link.label === 'Paper');
      return paper ? paper.url : '';
    },
    extraLinks() {
      return (this.pub.links || []).filter((link) => link.label !== 'Paper');
    },
    authorsHtml() {
      const text = this.pub.authors || '';
      const escaped = escapeHtml(text);
      if (!this.pub.self) return escaped;
      const re = new RegExp(`(${escapeRegExp(this.pub.self)})`, 'g');
      return escaped.replace(re, '<b>$1</b>');
    }
  },
  methods: {
    hlText(text) {
      return highlightText(text, this.searchTerms);
    },
    hlHtml(html) {
      return highlightHtml(html, this.searchTerms);
    }
  }
};
</script>

