<template>
    <div>
        <h1></h1>
        <article>
        <div class='image-left container' style='margin: auto;'>
            <video class='homevideo1' id='videoElement' style='opacity: 0;' muted autoplay playsinline webkit-playsinline preload='metadata'>
                <source src='/assets/vid/home1.mp4' type='video/mp4'>
                Your browser does not support this website.
            </video>
            <img id='imageElement' src='/assets/img/home1.jpg' alt='Travel' class='fallback-image' style='display: none; opacity: 0;'>
            <div class='transition-overlay' id='transitionOverlay'></div>
            <div class='description-overlay' id='descriptionOverlay'>
                <div class='description-content' id='descriptionContent'></div>
            </div>
            <div class='welcome-text'>
                <h1 id='welcomeTitle' style='color: transparent;'>WELC<span id='compassContainer'><i class='far fa-compass' id='compassIcon'></i></span>ME</h1>
                <h2 id='welcomeSubtitle' style='color: transparent;'>Hi, I'm Henry, a senior at HKU. I like wandering into new places and noticing small things. Take a look around.</h2>
            </div>
            <aside
                class='home-margin-note home-margin-note-left'
                :class="{ 'home-intro-visible': homeIntroStage >= 2 }"
                aria-label='Current scene'
            >
                <transition name='home-scene-fade' mode='out-in'>
                    <div v-if='homeScene' :key='homeScene.src'>
                        <span class='home-margin-kicker'>{{ homeScene.date }}</span>
                        <strong>{{ homeScene.place }}</strong>
                        <span>{{ homeScene.region }}</span>
                    </div>
                </transition>
            </aside>
            <aside
                id='currently'
                class='home-margin-note home-margin-note-right'
                :class="{ 'home-intro-visible': homeIntroStage >= 4 }"
                aria-label='Currently'
            >
                <span class='home-margin-kicker'>Currently</span>
                <nav class='home-current-list' aria-label='Current work and ideas'>
                    <router-link
                        v-for='item in currentItems'
                        :key='item.id'
                        :to="{ path: item.route, hash: `#${item.anchor}` }"
                    >
                        <strong>{{ item.title }}</strong>
                        <span>{{ item.subtitle }}</span>
                    </router-link>
                </nav>
                <router-link class='home-margin-cv' to='/cv'>Open CV <span aria-hidden='true'>↗</span></router-link>
            </aside>
        </div>

        <div id='overlay'></div>

        <br>

        <!-- Retired for now, but kept in place in case the homepage quote returns.
        <h3 id='welcomeQuote' style='color: transparent;'>Life is an endless adventure<br>into the unknown</h3>
        -->
        <div id='homeAsk' class='home-ask' style='color: transparent;'>
            <div class='home-ask-bar' @click='focusInput'>
                <svg class='home-ask-spark' viewBox='0 0 24 24' aria-hidden='true'><path d='M12 3 L13.5 9.5 L20 11 L13.5 12.5 L12 19 L10.5 12.5 L4 11 L10.5 9.5 Z'/></svg>
                <div class='home-ask-input-wrap'>
                    <input
                        ref='askInput'
                        type='text'
                        class='home-ask-input'
                        v-model='askText'
                        placeholder=''
                        aria-label='Ask this site anything about Henry'
                        @focus='askFocused = true'
                        @blur='askFocused = false'
                        @compositionstart='askComposing = true'
                        @compositionend='askComposing = false'
                        @keydown.enter='submitAsk($event)'
                    >
                    <transition v-if='showExamplePrompt' name='home-prompt-fade' mode='out-in'>
                        <span
                            :key='askPromptText'
                            class='home-ask-prompt'
                            aria-hidden='true'
                        >{{ askPromptText }}</span>
                    </transition>
                    <span
                        v-else-if='inputEmpty'
                        class='home-ask-prompt'
                        aria-hidden='true'
                    >{{ askPromptText }}</span>
                </div>
            </div>
            <div v-if='askAnswerText || askBusy || askError || askMapVisible' class='home-ask-result'>
                <template v-if='askAnswerText'>
                    <transition
                        appear
                        @before-enter='beforeHomeAskEnter'
                        @enter='enterHomeAsk'
                        @leave='leaveHomeAsk'
                    >
                        <p class='home-ask-answer'>{{ askAnswerText }}</p>
                    </transition>
                </template>
                <p v-else-if='askBusy' class='home-ask-status'>{{ askStatus }}</p>
                <p v-else-if='askError' class='home-ask-status'>{{ askErrorText }}</p>

                <div v-if='homeCitedSources.length && !askBusy' class='home-ask-sources-wrap'>
                    <span class='home-ask-sources-label' aria-hidden='true'>Sources</span>
                    <transition-group
                        appear
                        tag='div'
                        class='home-ask-sources'
                        @before-enter='beforeHomeChipEnter'
                        @enter='enterHomeChip'
                        @leave='leaveHomeChip'
                    >
                        <button
                            v-for='s in homeCitedSources'
                            :key='s.id'
                            class='home-ask-source'
                            :class='{ "is-previewed": hoveredSourceId === s.id }'
                            @mouseenter='hoveredSourceId = s.id'
                            @mouseleave='hoveredSourceId = null'
                            @focus='hoveredSourceId = s.id'
                            @blur='hoveredSourceId = null'
                            @click='goSource(s)'
                        >{{ s.page }} › {{ s.title }}</button>
                    </transition-group>
                    <transition name='home-preview-fade'>
                        <div v-if='sourcePreview' :key='sourcePreview.id' class='home-ask-preview' aria-hidden='true'>
                            <span class='home-ask-preview-kicker'>{{ sourcePreview.page }} › {{ sourcePreview.title }}</span>
                            <p class='home-ask-preview-text'>{{ sourcePreview.snippet }}</p>
                        </div>
                    </transition>
                </div>

                <div v-if='followUpQuestions.length && askAnswerText && !askBusy' class='home-ask-followups'>
                    <span class='home-ask-followups-label' aria-hidden='true'>Keep exploring</span>
                    <div class='home-ask-followups-list'>
                        <button
                            v-for='q in followUpQuestions'
                            :key='q'
                            type='button'
                            class='home-ask-followup'
                            @click='askFollowUp(q)'
                        >{{ q }}</button>
                    </div>
                </div>

                <div v-if='askMapVisible || askBusy' class='home-ask-map-shell'>
                    <EmbeddingMap
                        ref='homeAskMap'
                        class='home-ask-map'
                        compact
                        fit-stage
                        initial-view-mode='3d'
                        :monochrome='true'
                        :show-controls='false'
                        :show-view-toggle='false'
                        :show-caption='false'
                        :show-hits='false'
                        :allow-navigation='homeAskMapNavigable'
                        @ready='syncHomeAskMap'
                    />
                </div>
            </div>
        </div>
        </article>
    </div>
</template>
  
<script>
    import EmbeddingMap from './EmbeddingMap.vue';
    import { animate } from 'motion';
    import { askConfigured, askStream, askErrorMessage } from '../utils/askSite';
    import { ASK_SAMPLE_PROMPTS, HOME_ASK_INTRO_PROMPT } from '../utils/askPrompts';
    import { currentlyItems } from '../data/currently';
    import { semanticTopK } from '../utils/semanticSearch';
    import {
        allAskContexts,
        askAnswerFollowUps,
        citedSourcesFromAnswer,
        cleanAskAnswer,
        cleanAskContextText,
        groundAskFollowUps,
        loadSearchItems,
        sourceDisplayTitle,
        takeRetrievalTrace,
    } from '../utils/askRetrieval';
    import { logAskClient, logEvent, newAskContext } from '../utils/askTelemetry';

    // Keep in sync with slugify() in scripts/build-search-index.mjs and SearchPalette.vue.
    function slugify(s) {
        return String(s)
            .replace(/<[^>]+>/g, '')
            .toLowerCase()
            .trim()
            .replace(/[^\w\s-]/g, '')
            .replace(/\s+/g, '-')
            .replace(/-+/g, '-')
            .slice(0, 80);
    }

    // Assign slug ids to the current page's headings / timeline titles, mirroring the
    // build-time extractor, so a source link can deep-link to its section.
    function assignAnchors() {
        const root = document.querySelector('.content-container');
        if (!root) return;
        const useEntries = !!root.querySelector('li.title');
        const els = useEntries ? root.querySelectorAll('li.title') : root.querySelectorAll('h2, h3');
        const seen = new Set();
        els.forEach((el) => {
            const base = slugify(el.textContent);
            if (!base) return;
            let slug = base;
            let n = 2;
            while (seen.has(slug)) slug = `${base}-${n++}`;
            seen.add(slug);
            el.id = slug;
        });
    }

    // Land on the entry's visual top, not the title: research/projects keep the date label
    // at the top (.timeline-event); education/experience keep the school/company logo at the
    // top (the entry <section>).
    function scrollTargetFor(el) {
        const te = el.closest('.timeline-event');
        if (te) return te;
        if (el.matches && el.matches('li.title')) {
            const sec = el.closest('section');
            if (sec) return sec;
        }
        return el;
    }

    // Module-level (not a component method) on purpose: clicking a source navigates away
    // and UNMOUNTS IndexPage, so any `this`-bound retry would die. These plain functions
    // keep retrying against the freshly-rendered page until the anchor exists.
    function scrollToAnchor(anchor, findAttempt = 0) {
        if (!anchor) {
            window.scrollTo({ top: 0, behavior: 'smooth' });
            return;
        }
        assignAnchors();
        const el = document.getElementById(anchor);
        if (el) {
            const target = scrollTargetFor(el);
            target.scrollIntoView({ behavior: 'smooth', block: 'start' });
            return;
        }
        if (findAttempt < 25) setTimeout(() => scrollToAnchor(anchor, findAttempt + 1), 120);
    }

    const HOME_ASK_STORAGE_KEY = 'homeAskState:v1';
    let homeAskMemory = null;

    function compactAskSources(sources) {
        return (sources || []).map((s) => ({
            id: s.id,
            route: s.route,
            anchor: s.anchor || '',
            page: s.page,
            title: s.title,
        }));
    }

    function readHomeAskState() {
        if (homeAskMemory) return homeAskMemory;
        if (typeof window === 'undefined' || !window.sessionStorage) return null;
        try {
            const raw = window.sessionStorage.getItem(HOME_ASK_STORAGE_KEY);
            homeAskMemory = raw ? JSON.parse(raw) : null;
            return homeAskMemory;
        } catch (err) {
            return null;
        }
    }

    function writeHomeAskState(state) {
        homeAskMemory = state;
        if (typeof window === 'undefined' || !window.sessionStorage) return;
        try {
            window.sessionStorage.setItem(HOME_ASK_STORAGE_KEY, JSON.stringify(state));
        } catch (err) {
            // Storage can be unavailable in private modes; in-memory state still covers route switches.
        }
    }

    export default {
        name: 'IndexPage',
        components: { EmbeddingMap },
        data() {
            return {
                scriptModule: null,
                askText: '',
                askFocused: false,
                askComposing: false,
                askAnswer: '',
                askSources: [],
                askBusy: false,
                askError: '',
                askStatus: '',
                askMapVisible: false,
                askMapHits: [],
                askMapLabel: '',
                askMapFinalized: false,
                askIntroPrompt: HOME_ASK_INTRO_PROMPT,
                askQuestions: ASK_SAMPLE_PROMPTS,
                askQIndex: -1,
                askRotate: null,
                homeScene: null,
                currentItems: currentlyItems,
                homeIntroStage: 0,
                hoveredSourceId: null,
                // null = AI follow-ups not grounded yet; [] = grounded, none passed.
                groundedFollowUps: null,
            };
        },
        computed: {
            // Idle: cycle through real example questions in a separate overlay so
            // each change can fade instead of snapping like a native placeholder.
            askPromptText() {
                if (this.askFocused) return 'Ask anything about Henry…';
                if (this.askQIndex < 0) return this.askIntroPrompt;
                return this.askQuestions[this.askQIndex];
            },
            // Treat an in-progress IME composition (pinyin not yet committed) as "not empty",
            // so the placeholder hides the moment the user starts typing — otherwise it stays
            // up and overlaps the characters being composed in the input.
            inputEmpty() {
                return !this.askText && !this.askComposing;
            },
            showExamplePrompt() {
                return !this.askFocused && this.inputEmpty;
            },
            askAnswerText() {
                return cleanAskAnswer(this.askAnswer);
            },
            homeCitedSources() {
                return citedSourcesFromAnswer(this.askAnswer, this.askSources);
            },
            askErrorText() {
                return askErrorMessage();
            },
            homeAskMapNavigable() {
                // Clickable once the request settles, whether it produced an answer
                // or errored out: the map still holds the retrieved passages, so the
                // visitor can jump into them even when generation failed.
                return !this.askBusy && (!!this.askAnswerText || !!this.askError);
            },
            // Hovering a cited source peeks at its passage without leaving the page.
            sourcePreview() {
                if (!this.hoveredSourceId) return null;
                const s = this.homeCitedSources.find((x) => x.id === this.hoveredSourceId);
                if (!s) return null;
                const text = cleanAskContextText(s.body || '').replace(/\s+/g, ' ').trim();
                const snippet = text
                    ? (text.length > 230 ? `${text.slice(0, 230).trim()}…` : text)
                    : 'Open the passage to read it.';
                return { id: s.id, page: s.page, title: s.title, snippet };
            },
            // A small set of next questions: deepen into the cited passages, then
            // fall back to the general pool. One answer becomes a short exploration.
            followUpQuestions() {
                if (this.askBusy || !this.askAnswerText) return [];
                // Prefer the questions the model wrote with its answer; they are
                // specific to what was just discussed. Fall back to a hand-picked
                // mix when the model did not provide any.
                const rawAiFollowUps = askAnswerFollowUps(this.askAnswer);
                if (this.groundedFollowUps !== null) {
                    // Grounding verdict is in: show the ones that can retrieve a
                    // passage, or fall through to hand-picked questions.
                    if (this.groundedFollowUps.length) return this.groundedFollowUps;
                } else if (rawAiFollowUps.length) {
                    // Grounding still running; show the model's list meanwhile.
                    return rawAiFollowUps;
                }
                const current = String(this.askText || '').trim().toLowerCase();
                const candidates = [];
                for (const s of this.homeCitedSources) {
                    const t = String(s.title || '').trim();
                    if (t) candidates.push(`Tell me more about ${t}`);
                }
                for (const p of ASK_SAMPLE_PROMPTS) candidates.push(p);
                const seen = new Set();
                const out = [];
                for (const c of candidates) {
                    const k = String(c).trim().toLowerCase();
                    if (!k || k === current || seen.has(k)) continue;
                    seen.add(k);
                    out.push(String(c).trim());
                    if (out.length >= 3) break;
                }
                return out;
            },
        },
        watch: {
            askText: 'persistHomeAskState',
            askAnswer: 'persistHomeAskState',
            askSources: {
                handler: 'persistHomeAskState',
                deep: true,
            },
            askError: 'persistHomeAskState',
            askStatus: 'persistHomeAskState',
            askMapVisible: 'persistHomeAskState',
            askMapHits: {
                handler: 'persistHomeAskState',
                deep: true,
            },
        },
        created() {
            this.restoreHomeAskState();
        },
        async mounted() {
            this._askSeq = 0;
            this._onHomeAskReady = this.startAskRotation;
            this._onHomeSceneChange = (event) => {
                this.homeScene = event.detail || null;
            };
            this._onHomeIntroStage = (event) => {
                const stage = Number(event.detail && event.detail.stage);
                if (Number.isFinite(stage)) this.homeIntroStage = stage;
            };
            window.addEventListener('home-ask-ready', this._onHomeAskReady);
            window.addEventListener('home-scene-change', this._onHomeSceneChange);
            window.addEventListener('home-intro-stage', this._onHomeIntroStage);
            // Scrolling away the pointer's anchor hides the hover preview
            // immediately, so it never floats at a stale position.
            this._onAnyScroll = () => {
                if (this.hoveredSourceId) this.hoveredSourceId = null;
            };
            window.addEventListener('scroll', this._onAnyScroll, { capture: true, passive: true });
            // Dynamically import the script when the component is mounted
            this.scriptModule = await import('../assets/js/home.js');
            if (this.scriptModule && this.scriptModule.initScript) {
                this.scriptModule.initScript();
            }
            // Restored ask state is compacted for storage (no source bodies);
            // refill them from the search index so hover previews work again.
            this.rehydrateAskSources();
            if (this.askAnswer) this.groundAiFollowUps(this._askSeq);
        },
        unmounted() {
            // Clean up the script when the component is unmounted
            if (this._homeAnims) {
                this._homeAnims.forEach((animation) => animation.stop());
                this._homeAnims.clear();
            }
            if (this.scriptModule && this.scriptModule.cleanupScript) {
                this.scriptModule.cleanupScript();
            }
            this.scriptModule = null; // Optionally, clear the reference to the module
            if (this._onHomeAskReady) window.removeEventListener('home-ask-ready', this._onHomeAskReady);
            if (this._onHomeSceneChange) window.removeEventListener('home-scene-change', this._onHomeSceneChange);
            if (this._onHomeIntroStage) window.removeEventListener('home-intro-stage', this._onHomeIntroStage);
            if (this._onAnyScroll) window.removeEventListener('scroll', this._onAnyScroll, { capture: true, passive: true });
            if (this.askRotate) clearInterval(this.askRotate);
            if (this._homeAskMapFinalTimer) clearTimeout(this._homeAskMapFinalTimer);
            if (this.askBusy) {
                this.askBusy = false;
                this.askStatus = this.askAnswer ? '' : 'Paused.';
                this.persistHomeAskState();
            }
            this._askSeq += 1;
        },
        methods: {
            homeReduceMotion() {
                return window.matchMedia
                    && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
            },
            trackHomeAnim(animation) {
                if (!this._homeAnims) this._homeAnims = new Set();
                this._homeAnims.add(animation);
                return animation;
            },
            untrackHomeAnim(animation) {
                if (this._homeAnims) this._homeAnims.delete(animation);
            },
            // Same "forming" entrance as the search palette: the answer settles
            // in when the first tokens arrive, and cited sources cascade in.
            beforeHomeAskEnter(el) {
                el.style.opacity = '0';
                el.style.transform = 'translateY(6px)';
            },
            enterHomeAsk(el, done) {
                if (this.homeReduceMotion()) {
                    el.style.opacity = '';
                    el.style.transform = '';
                    done();
                    return;
                }
                let settled = false;
                const finish = () => {
                    if (settled) return;
                    settled = true;
                    el.style.opacity = '';
                    el.style.transform = '';
                    this.untrackHomeAnim(animation);
                    done();
                };
                const animation = this.trackHomeAnim(animate(el, {
                    opacity: [0, 1],
                    transform: ['translateY(6px)', 'translateY(0px)'],
                }, {
                    type: 'spring',
                    bounce: 0,
                    duration: 0.4,
                    onComplete: finish,
                }));
                window.setTimeout(finish, 1000);
            },
            leaveHomeAsk(el, done) {
                if (this.homeReduceMotion()) {
                    done();
                    return;
                }
                let settled = false;
                const finish = () => {
                    if (settled) return;
                    settled = true;
                    this.untrackHomeAnim(animation);
                    done();
                };
                const animation = this.trackHomeAnim(animate(el, {
                    opacity: [1, 0],
                    transform: ['translateY(0px)', 'translateY(-4px)'],
                }, {
                    type: 'spring',
                    bounce: 0,
                    duration: 0.18,
                    onComplete: finish,
                }));
                window.setTimeout(finish, 400);
            },
            beforeHomeChipEnter(el) {
                el.style.opacity = '0';
                el.style.transform = 'translateY(4px)';
            },
            enterHomeChip(el, done) {
                if (this.homeReduceMotion()) {
                    el.style.opacity = '';
                    el.style.transform = '';
                    done();
                    return;
                }
                const index = Math.max(0, Array.from(el.parentNode ? el.parentNode.children : []).indexOf(el));
                let settled = false;
                const finish = () => {
                    if (settled) return;
                    settled = true;
                    el.style.opacity = '';
                    el.style.transform = '';
                    this.untrackHomeAnim(animation);
                    done();
                };
                const animation = this.trackHomeAnim(animate(el, {
                    opacity: [0, 1],
                    transform: ['translateY(4px)', 'translateY(0px)'],
                }, {
                    type: 'spring',
                    bounce: 0,
                    duration: 0.3,
                    delay: index * 0.045,
                    onComplete: finish,
                }));
                window.setTimeout(finish, 1000);
            },
            leaveHomeChip(el, done) {
                if (this.homeReduceMotion()) {
                    done();
                    return;
                }
                let settled = false;
                const finish = () => {
                    if (settled) return;
                    settled = true;
                    this.untrackHomeAnim(animation);
                    done();
                };
                const animation = this.trackHomeAnim(animate(el, {
                    opacity: [1, 0],
                    transform: ['translateY(0px)', 'translateY(-2px)'],
                }, {
                    type: 'spring',
                    bounce: 0,
                    duration: 0.12,
                    onComplete: finish,
                }));
                window.setTimeout(finish, 400);
            },
            restoreHomeAskState() {
                // The root route (#/) is the fresh landing-home state. It should not
                // inherit a previously restored Ask/map result. Keep restoration only
                // for /home, which is the intentional return-from-another-tab state.
                if (this.$route.path === '/') return;

                const saved = readHomeAskState();
                if (!saved) return;
                this.askText = saved.askText || '';
                this.askAnswer = saved.askAnswer || '';
                this.askSources = Array.isArray(saved.askSources) ? saved.askSources : [];
                this.askError = saved.askError || '';
                this.askStatus = saved.askStatus || '';
                this.askMapVisible = !!saved.askMapVisible;
                this.askMapHits = Array.isArray(saved.askMapHits) ? saved.askMapHits : [];
                this.askMapLabel = saved.askMapLabel || '';
                this.askMapFinalized = !!saved.askMapFinalized;
            },
            persistHomeAskState() {
                writeHomeAskState({
                    askText: this.askText,
                    askAnswer: this.askAnswer,
                    askSources: compactAskSources(this.askSources),
                    askError: this.askError,
                    askStatus: this.askStatus,
                    askMapVisible: this.askMapVisible,
                    askMapHits: this.askMapHits,
                    askMapLabel: this.askMapLabel,
                    askMapFinalized: this.askMapFinalized,
                });
            },
            startAskRotation() {
                if (this.askRotate) return;
                this.askRotate = setInterval(() => {
                    if (!this.askFocused && !this.askText) {
                        this.askQIndex = this.nextRandomAskIndex();
                    }
                }, 3600);
            },
            nextRandomAskIndex() {
                const count = this.askQuestions.length;
                if (count <= 1) return this.askQIndex < 0 ? 0 : this.askQIndex;

                if (this.askQIndex < 0) {
                    return Math.floor(Math.random() * count);
                }

                let next = Math.floor(Math.random() * (count - 1));
                if (next >= this.askQIndex) next += 1;
                return next;
            },
            focusInput() {
                if (this.$refs.askInput) this.$refs.askInput.focus();
            },
            submitAsk(e) {
                if (this.askComposing || (e && e.isComposing)) return; // let IME commit first
                this.askHome(this.askText.trim());
            },
            askFollowUp(q) {
                const question = String(q || '').trim();
                if (!question) return;
                this.askText = question;
                this.askQIndex = -1;
                this.hoveredSourceId = null;
                logEvent('ask_followup_click', { question, surface: 'home' }, this._lastAskEventId || null);
                this.submitAsk();
            },
            async askHome(text) {
                const question = String(text || '').trim();
                if (!question || !askConfigured()) return;
                const seq = ++this._askSeq;
                this.askBusy = true;
                this.askError = '';
                this.askAnswer = '';
                this.askSources = [];
                this.askMapVisible = true;
                this.askMapHits = [];
                this.askMapLabel = question;
                this.askMapFinalized = false;
                this.groundedFollowUps = null;
                this.$nextTick(() => this.prepareHomeAskMap(question, seq));

                const telemetry = newAskContext('home');
                this._lastAskEventId = telemetry.event_id;
                const startedAt = Date.now();
                let firstTokenAt = null;
                let trace = null;
                let answer = '';
                let sources = [];
                let payloadLength = 0;
                let payloadChars = 0;
                let failure = '';

                try {
                    this.askStatus = 'Thinking…';
                    // Keep all regular site context, then add fragment chunks retrieved for this question.
                    const contexts = await allAskContexts(question);
                    trace = takeRetrievalTrace();
                    sources = contexts;
                    if (seq !== this._askSeq) return;
                    this.askSources = contexts;
                    const payload = contexts.map(c => ({
                        page: c.page,
                        title: sourceDisplayTitle(c),
                        text: cleanAskContextText(c.body),
                    }));
                    payloadLength = payload.length;
                    payloadChars = payload.reduce((sum, c) => sum + String(c.text || '').length, 0);
                    const stream = askStream(question, payload, {
                        meta: {
                            event_id: telemetry.event_id,
                            session_id: telemetry.session_id,
                            turn_index: telemetry.turn_index,
                            surface: telemetry.surface,
                        },
                        onFirstToken: () => { firstTokenAt = Date.now(); },
                    });
                    for await (const tok of stream) {
                        if (seq !== this._askSeq) return;
                        answer += tok;
                        this.askAnswer += tok;
                    }
                    if (seq === this._askSeq) {
                        this.finishHomeAskMap();
                        // Vet the model's follow-ups against the site's own
                        // embeddings so the chips never suggest something the
                        // site cannot answer.
                        this.groundAiFollowUps(seq);
                    }
                } catch (err) {
                    failure = String(err?.message || err).slice(0, 200);
                    if (seq === this._askSeq) this.askError = 'error';
                    console.error('home ask failed:', err);
                } finally {
                    if (seq === this._askSeq) this.askBusy = false;
                    const finishedAt = Date.now();
                    logAskClient(telemetry, {
                        question,
                        retrieval_ms: trace ? trace.retrieval_ms : null,
                        ttft_ms: firstTokenAt ? firstTokenAt - startedAt : null,
                        stream_ms: firstTokenAt ? finishedAt - firstTokenAt : null,
                        total_ms: finishedAt - startedAt,
                        answer_len: answer.length,
                        aborted: seq !== this._askSeq,
                        error: failure || null,
                        n_contexts_sent: payloadLength,
                        contexts_chars: payloadChars,
                        n_lex: trace ? trace.n_lex : null,
                        n_sem: trace ? trace.n_sem : null,
                        sem_top_score: trace ? trace.sem_top_score : null,
                        cited: answer
                            ? citedSourcesFromAnswer(answer, sources).map(s => ({
                                n: s.n,
                                chunk_id: s.chunk_id,
                                route: s.route,
                                anchor: s.anchor || null,
                                title: s.title || null,
                            }))
                            : [],
                        retrieval: trace ? trace.rows : [],
                    });
                }
            },
            async prepareHomeAskMap(question, seq) {
                try {
                    const hits = await semanticTopK(question, 8);
                    if (seq !== this._askSeq) return;
                    this.askMapHits = hits.map((h) => ({ id: h.id, score: h.score }));
                    this.askMapLabel = question;
                    const map = this.$refs.homeAskMap;
                    if (map && map.showExternalHits) {
                        // While waiting for the answer: keep the full map in view and just
                        // light up the retrieved passages, no zoom-in yet.
                        map.showExternalHits(this.askMapHits, {
                            label: question,
                            focus: false,
                            keepCentered: false,
                            duration: 900,
                        });
                    }
                } catch (err) {
                    console.warn('home ask map failed:', err);
                }
            },
            citedSourceItems() {
                const cited = new Set();
                const re = /\[([\d,\s]+)\]/g;
                let m;
                while ((m = re.exec(this.askAnswer))) {
                    m[1].split(/[\s,]+/).filter(Boolean).forEach((n) => cited.add(parseInt(n, 10)));
                }
                return this.askSources.filter((source, i) => cited.has(i + 1) && source && source.id != null);
            },
            finishHomeAskMap() {
                const hits = this.citedSourceItems().map((source) => ({ id: source.id, score: 0.92 }));
                this.askMapHits = hits;
                this.askMapLabel = hits.length ? 'cited passages' : this.askMapLabel;
                this.askMapFinalized = true;
                const map = this.$refs.homeAskMap;
                if (!map || !map.showExternalHits) return;
                if (this._homeAskMapFinalTimer) clearTimeout(this._homeAskMapFinalTimer);
                // Answer is in: zoom in onto the cited passages. (With no citations the
                // hit list is empty and the map falls back to the full view.)
                map.showExternalHits(hits, {
                    label: this.askMapLabel,
                    focus: true,
                    keepCentered: true,
                    duration: 850,
                });
            },
            async rehydrateAskSources() {
                const missing = this.askSources.filter((s) => !s.body);
                if (!missing.length) return;
                try {
                    const items = await loadSearchItems();
                    const byKey = new Map();
                    for (const it of items) byKey.set(`${it.route}#${it.anchor || ''}`, it);
                    let changed = false;
                    const hydrated = this.askSources.map((s) => {
                        if (s.body) return s;
                        const it = byKey.get(`${s.route}#${s.anchor || ''}`);
                        if (!it) return s;
                        changed = true;
                        return { ...s, body: it.body, chunk_id: String(it.id) };
                    });
                    if (changed) {
                        this.askSources = hydrated;
                        this.persistHomeAskState();
                    }
                } catch (e) {
                    // Keep the fallback preview text; Ask itself still works.
                }
            },
            async groundAiFollowUps(seq) {
                const questions = askAnswerFollowUps(this.askAnswer);
                if (!questions.length) {
                    if (seq === this._askSeq) this.groundedFollowUps = [];
                    return;
                }
                const grounded = await groundAskFollowUps(questions);
                if (seq !== this._askSeq) return;
                this.groundedFollowUps = grounded;
            },
            syncHomeAskMap() {
                const map = this.$refs.homeAskMap;
                if (!map || !map.showExternalHits || !this.askMapHits.length) return;
                map.showExternalHits(this.askMapHits, {
                    label: this.askMapLabel,
                    // Full map until the answer is finalized, then focus on the cited passages.
                    focus: this.askMapFinalized,
                    keepCentered: this.askMapFinalized,
                    duration: 500,
                });
            },
            goSource(source) {
                if (!source) return;
                logEvent('ask_source_click', {
                    chunk_id: source.chunk_id || null,
                    route: source.route,
                    anchor: source.anchor || null,
                    title: source.title || null,
                    surface: 'home',
                }, this._lastAskEventId || null);
                const samePage = this.$route.path === source.route;

                if (!samePage) {
                    // Cross-page landings are handled centrally once the new
                    // page has mounted; keep the anchor in the URL so the
                    // landing knows where to go.
                    const target = { path: source.route };
                    if (source.anchor) target.hash = `#${source.anchor}`;
                    this.$router.push(target).catch(() => {});
                    return;
                }

                scrollToAnchor(source.anchor);
            },
        },
    }
</script>
 
