// Shared helpers for landing on a section after navigation. The slug scheme
// must stay in sync with scripts/build-search-index.mjs and the in-page
// assignAnchors() helpers in SearchPalette.vue / IndexPage.vue.
export function slugify(s) {
  return String(s)
    .replace(/<[^>]+>/g, '')
    .toLowerCase()
    .trim()
    .replace(/[^\w\s-]/g, '')
    .replace(/\s+/g, '-')
    .replace(/-+/g, '-')
    .slice(0, 80);
}

// Assign slug ids to the current page's headings / timeline titles, mirroring
// the build-time extractor, so a source link can deep-link to its section.
export function assignAnchors(root) {
  if (!root) return;
  const useEntries = !!root.querySelector('li.title');
  const els = useEntries ? root.querySelectorAll('li.title') : root.querySelectorAll('h2, h3');
  const seen = new Set();
  els.forEach((el) => {
    const base = slugify(el.textContent);
    if (!base) return;
    let slug = base;
    let n = 2;
    while (seen.has(slug)) slug = `${base}-${n++}`;
    seen.add(slug);
    el.id = slug;
  });
}

// Land on the entry's visual top, not the title: research/projects keep the
// date label at the top (.timeline-event); education/experience keep the
// school/company block top (the entry <section>).
export function scrollTargetFor(el) {
  const te = el.closest('.timeline-event');
  if (te) return te;
  if (el.matches && el.matches('li.title')) {
    const sec = el.closest('section');
    if (sec) return sec;
  }
  return el;
}

// Reveal animations start entries translated down 16-20px; the transform
// resolves when the entry enters the viewport. scrollIntoView aims at the
// transformed box and lands short once the transform settles, so read the
// settled layout position instead.
function revealTranslateY(el) {
  let total = 0;
  let node = el;
  while (node && node !== document.body) {
    const tr = getComputedStyle(node).transform;
    if (tr && tr !== 'none') {
      const m2 = tr.match(/^matrix\(([^)]+)\)$/);
      if (m2) {
        const parts = m2[1].split(',').map(parseFloat);
        if (parts.length >= 6) total += parts[5];
      } else {
        const m3 = tr.match(/^matrix3d\(([^)]+)\)$/);
        if (m3) {
          const parts = m3[1].split(',').map(parseFloat);
          if (parts.length >= 16) total += parts[13];
        }
      }
    }
    node = node.parentElement;
  }
  return total;
}

// Smoothly scroll to an element id, honouring the target's own scroll-margin
// and the reveal animation's settled position. Returns true when the element
// was found and scrolled to.
export function landOnId(id, { smooth = true, root = null } = {}) {
  if (!id) return false;
  const reduceMotion =
    typeof window !== 'undefined' &&
    window.matchMedia &&
    window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  const behavior = smooth && !reduceMotion ? 'smooth' : 'auto';

  let el = document.getElementById(id);
  if (!el) {
    assignAnchors(root || document.querySelector('.content-container'));
    el = document.getElementById(id);
  }
  if (!el) return false;

  const target = scrollTargetFor(el);
  // Start the landing block's reveal now so its transform settles before (or
  // while) we arrive, then scroll to the settled layout position.
  let node = target;
  while (node && node !== document.body) {
    if (node.classList && node.classList.contains('scroll-reveal-item')) {
      node.classList.add('scroll-reveal-visible');
    }
    node = node.parentElement;
  }

  const margin = parseFloat(getComputedStyle(target).scrollMarginTop) || 0;
  const rect = target.getBoundingClientRect();
  const top = Math.max(0, rect.top + window.scrollY - revealTranslateY(target) - margin);
  window.scrollTo({ top, behavior });
  return true;
}

let activeSettleStop = null;

// Same landing as landOnId, plus a settle pass: while late resources (fonts,
// lazy images, window load) can still shift the layout, keep re-checking the
// target's position and glide it back to the scroll-margin spot whenever it
// drifts. Waiting for everything to load first is not an option for lazy
// images, so we scroll immediately and correct as the page settles. The
// monitor stops on user scroll/touch/keyboard takeover or after maxWait.
export function settleScrollToId(id, { smooth = true, root = null, maxWait = 3500 } = {}) {
  if (!id) return false;
  const reduceMotion =
    typeof window !== 'undefined' &&
    window.matchMedia &&
    window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  const behavior = smooth && !reduceMotion ? 'smooth' : 'auto';

  let el = document.getElementById(id);
  if (!el) {
    assignAnchors(root || document.querySelector('.content-container'));
    el = document.getElementById(id);
  }
  if (!el) return false;

  const target = scrollTargetFor(el);
  let node = target;
  while (node && node !== document.body) {
    if (node.classList && node.classList.contains('scroll-reveal-item')) {
      node.classList.add('scroll-reveal-visible');
    }
    node = node.parentElement;
  }
  const margin = parseFloat(getComputedStyle(target).scrollMarginTop) || 0;

  let live = true;
  const go = () => {
    if (!live || !target.isConnected) return;
    const rect = target.getBoundingClientRect();
    const top = Math.max(0, rect.top + window.scrollY - revealTranslateY(target) - margin);
    window.scrollTo({ top, behavior });
  };
  const check = () => {
    if (!live) return;
    if (!target.isConnected) {
      stop();
      return;
    }
    const rect = target.getBoundingClientRect();
    const drift = Math.abs(rect.top - revealTranslateY(target) - margin);
    if (drift > 3) go();
  };
  const stop = () => {
    if (!live) return;
    live = false;
    if (activeSettleStop === stop) activeSettleStop = null;
    window.removeEventListener('wheel', stop, { passive: true });
    window.removeEventListener('touchstart', stop, { passive: true });
    window.removeEventListener('keydown', stop);
  };

  // Only one settle monitor at a time: a newer click or navigation supersedes
  // an older landing, so stale corrections never fight the latest intent.
  if (activeSettleStop) activeSettleStop();
  activeSettleStop = stop;

  go();
  window.addEventListener('wheel', stop, { passive: true });
  window.addEventListener('touchstart', stop, { passive: true });
  window.addEventListener('keydown', stop);
  [...document.images].forEach((im) => {
    if (!im.complete) {
      im.addEventListener('load', check, { once: true });
      im.addEventListener('error', check, { once: true });
    }
  });
  window.addEventListener('load', check, { once: true });
  if (document.fonts && document.fonts.ready) {
    document.fonts.ready.then(check).catch(() => {});
  }
  window.setTimeout(stop, maxWait);
  return true;
}
